/* PRD 4 layer F: the equipment variants. There is no free item ID, so a variant is a shop item converted in place:
 * def_equip_variants (definitive_equipment.c, generated by tools/gen_equipment.py) gives each its new power or guard,
 * accuracy or evasion and bonus stats, written here into the item's RecordsWeapon / RecordsArmor; its ID, icon (type),
 * slot, group, wearers, charisma, price and forge recipe stay, and its name and description are en.txt's ITMNAM /
 * ITMINF overrides. The stats are read from the item's data wherever they are used (gamestate_get_stats, the shop's
 * preview, fightstg_rules_get_stats), never stored, so an old save's equipped item simply has the variant's stats.
 *
 * Like the rookies' MP (def_mp_hook), the data is written every time the hook runs and only when def_on: the port
 * snapshots the game's data at boot, before a replay script is known, and the reset restores that snapshot, so a
 * replay script keeps the disc's items and a reset run gets them again at its next hook. The values are absolute, so
 * a run that is already patched is written the same numbers again, never patched twice over. */
#include "common.h"
#include "records.h"

#include "definitive.h"

extern int def_on(void); /* port.h declares it under PC_PORT only; the host test builds without it */
extern RecordsItem *records_get_item(s32 i);
extern void port_log(const char *fmt, ...);

static void apply(const DefEquipVariant *v) {
    RecordsItem *it = records_get_item(v->item);
    int k;

    /* A row whose item is not the category it names is skipped rather than written through the wrong struct (the
     * generator checks it; this guards a table and a records.c that have drifted apart). */
    if (it == NULL || it->data == NULL) {
        return;
    }
    if (v->weapon && it->category == RECORDS_ITEM_WEAPON && it->type >= 2 && it->type <= 14) {
        RecordsWeapon *w = it->data;

        w->power = v->main;
        w->accuracy = v->hit;
        for (k = 0; k < 2; k++) {
            w->bonus_stats[k] = v->stats[k];
            w->bonus_values[k] = v->values[k];
        }
    } else if (!v->weapon && it->category == RECORDS_ITEM_ARMOR && it->type >= 15 && it->type <= 20) {
        RecordsArmor *a = it->data;

        a->guard = v->main;
        a->evasion = v->hit;
        for (k = 0; k < 2; k++) {
            a->bonus_stats[k] = v->stats[k];
            a->bonus_values[k] = v->values[k];
        }
    }
}

void def_variants_hook(void) {
    static int logged;
    int i;

    if (!DEF_EQUIP_ON || !def_on()) {
        return;
    }
    for (i = 0; i < def_equip_variant_count; i++) {
        apply(&def_equip_variants[i]);
    }
    if (!logged) {
        logged = 1;
        port_log("equipment: %d variants written", def_equip_variant_count);
    }
}

int def_variant_text_hidden(int file, int index) {
    int i;

    if (file != DEF_TEXT_ITMNAM && file != DEF_TEXT_ITMINF) {
        return 0;
    }
    if (DEF_EQUIP_ON && def_on()) {
        return 0;
    }
    for (i = 0; i < def_equip_variant_count; i++) {
        if (def_equip_variants[i].item == index) {
            return 1;
        }
    }
    return 0;
}
